#define MAX_STEPS 400
#define MAX_DIST 100.
#define SURF_DIST .001

#define FK(k) floatBitsToInt(k*k/7.)^floatBitsToInt(k)
float hash(float a, float b) {
    int x = FK(a), y = FK(b);
    return float((x*x+y)*(y*y-x)-x)/2.14e9;
}

vec3 erot(vec3 p, vec3 ax, float ro) {
  return mix(dot(ax, p)*ax, p, cos(ro)) + cross(ax,p)*sin(ro);
}

vec3 face(vec3 p) {
     vec3 a = abs(p);
     return step(a.yzx, a.xyz)*step(a.zxy, a.xyz)*sign(p);
}

float sdBox(vec3 p, vec3 s) {
    p = abs(p)-s;
	return length(max(p, 0.))+min(max(p.x, max(p.y, p.z)), 0.);
}

vec3 getRo() {
    vec2 m = iMouse.xy/iResolution.xy;

    vec3 ro = vec3(3, 1.6, 1.2);
   // ro.yz *= Rot(-m.y*3.14+1.);
   // ro.xz *= Rot(-m.x*6.2831);
    return ro;
}

float GetDist(vec3 p) {
    float d = sdBox(p, vec3(1.)) - 0.1;
    //p.y -= 0.4 * cross(p, normalize(vec3(0. * cc(0.01, 2.2 * p.x + iTime), 
    //                             100. + 0. * cos(p.y + iTime), 
    //                             -30. * fract(p.y * 10.)))).y;
    // i dont know what this does (lol)
    p.y -= 0.2 * cross(p, normalize(vec3(0., 
                                         80., 
                                         -2.5 * cos(p.y * 10.)))).y;
    p.y += 2.5 + 2. * thc(2.,-2. + 0.05 * p.x - 0.4 * iTime);
    p.z += 0.5 * thc(1.01, p.x + iTime);
    p.y += 0.5 * thc(1.01, p.z + 0.8 * iTime);
    d = p.y;
    return d;
}

float RayMarch(vec3 ro, vec3 rd, float z) {

    float dO=0.;
    float s = sign(z);
    for(int i=0; i<MAX_STEPS; i++) {
    	vec3 p = ro + rd*dO;
        float dS = GetDist(p);
        if (s != sign(dS)) { z *= 0.5; s = sign(dS); }
        if(abs(dS)<SURF_DIST || dO>MAX_DIST) break;
        dO += dS*z; 
    }

    return min(dO, MAX_DIST);
}

vec3 GetNormal(vec3 p) {
	float d = GetDist(p);
    vec2 e = vec2(.001, 0);

    vec3 n = d - vec3(
        GetDist(p-e.xyy),
        GetDist(p-e.yxy),
        GetDist(p-e.yyx));

    return normalize(n);
}

vec3 GetRayDir(vec2 uv, vec3 p, vec3 l, float z) {
    vec3 f = normalize(l-p),
        r = normalize(cross(vec3(0,1,0), f)),
        u = cross(f,r),
        c = f*z,
        i = c + uv.x*r + uv.y*u,
        d = normalize(i);
    return d;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord-.5*iResolution.xy)/iResolution.y;

    vec3 ro = getRo();
    vec3 q = 8. * vec3(cos(0.81 * iTime), 0.25, sin(iTime));
    vec3 rd = GetRayDir(uv, ro, vec3(0.), 1.);
    vec3 col = vec3(0);

    float d = RayMarch(ro, rd, 1.);

    float IOR = 1.05;
    if(d<MAX_DIST) {
        vec3 p = ro + rd * d;
        vec3 n = GetNormal(p);
        vec3 r = reflect(rd, n);

        vec3 pIn = p - 4. * SURF_DIST * n;
        vec3 rdIn = refract(rd, n, 1./IOR);
        float dIn = RayMarch(pIn, rdIn, -1.);

        vec3 pExit = pIn + dIn * rdIn;
        vec3 nExit = -GetNormal(pExit); // *-1.; ?

        float dif = dot(n, normalize(vec3(1,2,3)))*.5+.5;
        col = vec3(dif);

        vec2 ipos = floor(2. * p.xz);
        float bg = mod(3. * ipos.x + 5. * ipos.y, 7.);
        col = mix(col, vec3(0.), exp(-10. * p.y));

        float mx = exp(-0.03 * length(p));
        //col = vec3(mx * bg);
        col = vec3(1);// * bg /7.;

        vec3 e = vec3(1);
        col *= pal(p.y * 1.6 + bg / 7., e, e, 0.14 * e, 0.4 * vec3(0,1,2)/3.);
        //col = vec3(1) * bg * 4. * exp(-2. * length(p-q));
        //col += (1.-bg) * mx;
        float fres = pow(1. + dot(rd, n), 5.);
        col *= fres;
        col = mix(vec3(0.85), col, mx);
    } else col = vec3(0.85);

    col = pow(col, vec3(.4545));	// gamma correction

    fragColor = vec4(col,1.0);
}

